set -e
cat > .cup-flag-tests.tmp <<'EOF'

  it('sinks the cup into a lined recess with a dark floor', () => {
    const builder = new HoleSceneBuilder();

    const result = builder.build(makeHole());

    const cup = meshNamed(result.group, 'test-hole-cup');
    const liner = meshNamed(result.group, 'test-hole-cup-liner');
    const floor = meshNamed(result.group, 'test-hole-cup-floor');

    expect(liner.scale.x).toBeCloseTo(0.5);
    expect(liner.scale.y).toBeCloseTo(0.4);
    expect(liner.position.y).toBeCloseTo(0);
    expect((liner.material as THREE.MeshStandardMaterial).side).toBe(THREE.BackSide);
    expect(floor.position.y).toBeCloseTo(-0.18);
    expect(floor.position.y).toBeLessThan(cup.position.y);
    builder.dispose();
  });

  it('plants a flag over the cup and takes the cloth colour from the course theme', () => {
    const builder = new HoleSceneBuilder();

    const result = builder.build(makeHole(), 'neon-city');

    const pole = meshNamed(result.group, 'test-hole-flag-pole');
    const flag = meshNamed(result.group, 'test-hole-flag');

    expect(pole.position.x).toBeCloseTo(0);
    expect(pole.position.z).toBeCloseTo(8);
    expect(pole.position.y).toBeGreaterThan(0.2);
    expect(pole.geometry).toBe(meshNamed(result.group, 'post').geometry);
    expect(flag.position.y).toBeGreaterThan(pole.position.y);
    expect(flag.geometry.getAttribute('position').count).toBe(3);
    expect((flag.material as THREE.MeshStandardMaterial).color.getHex()).toBe(0xff2bd6);
    expect((flag.material as THREE.MeshStandardMaterial).side).toBe(THREE.DoubleSide);
    builder.dispose();
  });

  it('falls back to the default cloth colour for an unknown theme and caches it per colour', () => {
    const builder = new HoleSceneBuilder();

    const unknown = meshNamed(builder.build(makeHole(), 'no-such-theme').group, 'test-hole-flag');
    const missing = meshNamed(builder.build(makeHole()).group, 'test-hole-flag');
    const neon = meshNamed(builder.build(makeHole(), 'neon-city').group, 'test-hole-flag');
    const neonAgain = meshNamed(builder.build(makeHole(), 'neon-city').group, 'test-hole-flag');

    expect(unknown.material).toBe(missing.material);
    expect(neon.material).toBe(neonAgain.material);
    expect(neon.material).not.toBe(missing.material);
    expect(neon.geometry).toBe(missing.geometry);
    builder.dispose();
  });

  it('keeps the cup parts in one child group so the hole mesh count is unchanged', () => {
    const builder = new HoleSceneBuilder();
    const hole = makeHole();

    const result = builder.build(hole);
    const assembly = result.group.getObjectByName('test-hole-cup-assembly');

    expect(assembly).toBeInstanceOf(THREE.Group);
    expect(assembly?.children).toHaveLength(5);
    expect(result.meshCount).toBe(hole.surfaces.length + hole.obstacles.length + 1);

    result.dispose();

    expect(assembly?.children).toHaveLength(0);
    builder.dispose();
  });
EOF
